constraints:
1 ≤ N ≤ 10^{3}
1 ≤ data of node ≤ 10^{4}
1 ≤ target ≤ 10^{4}
1 ≤ k ≤ 20

expected time complexity: O(N*logN)
expected auxiliary space: O(Height of tree)

standard_solution_code:
class Solution:

	def childnodes(self, root, k, res):
		if root is None:
			return
		if k == 0:
			res.append(root.data)
			return
		self.childnodes(root.left, k - 1, res)
		self.childnodes(root.right, k - 1, res)

	def findnodes(self, root, k, target, res):
		if root is None:
			return 0
		if root.data == target:
			self.childnodes(root, k, res)
			return 1
		fromleft = self.findnodes(root.left, k, target, res)
		fromright = self.findnodes(root.right, k, target, res)
		if fromleft > 0:
			if k - fromleft == 0:
				res.append(root.data)
			self.childnodes(root.right, k - fromleft - 1, res)
			return fromleft + 1
		if fromright > 0:
			if k - fromright == 0:
				res.append(root.data)
			self.childnodes(root.left, k - fromright - 1, res)
			return fromright + 1
		return 0

	def KDistanceNodes(self, root, target, k):
		res = []
		self.findnodes(root, k, target, res)
		res.sort()
		return res
